const Model={
byId:(db,id)=>db.find(r=>r.id===id),
nextId(db,kind){let prefix=SCHEMAS[kind].prefix;let n=1;while(db.some(r=>r.id===`${prefix}-${String(n).padStart(3,'0')}`))n++;return `${prefix}-${String(n).padStart(3,'0')}`},
subtotal:r=>(r.lines||[]).reduce((n,l)=>n+Number(l.amount||0),0),
gross(r){return this.subtotal(r)+Number(r.tax||0)-Number(r.discount||0)},
paid:r=>(r.payments||[]).reduce((n,p)=>n+p.amount,0),
net(r){return this.gross(r)-Number(r.withholding||0)},
relatedAmount(db,id){return db.filter(r=>r.kind==='bill'&&r.status==='POSTED').flatMap(r=>r.lines||[]).filter(l=>l.ref===id).reduce((n,l)=>n+Number(l.amount||0),0)},
period(start,frequency){let d=new Date(start+'T00:00:00Z');let months=({Bulanan:1,Triwulanan:3,Tahunan:12})[frequency]||1;let next=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+months,1));let end=new Date(next.getTime()-86400000);return {start,end:end.toISOString().slice(0,10),next:next.toISOString().slice(0,10)}},
arrival(period,day){let d=new Date(period+'T00:00:00Z');let last=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate();return `${period.slice(0,7)}-${String(Math.min(day,last)).padStart(2,'0')}`},
validate(db,r,stage='save'){
let errors=[];for(const s of SCHEMAS[r.kind].sections)for(const f of s.fields){let v=r[f.key];if(f.required&&(v===undefined||v===null||String(v).trim()===''))errors.push(`${f.label} wajib diisi.`);if(f.type==='number'&&v!==''&&v!==undefined&&(!Number.isFinite(Number(v))||Number(v)<0))errors.push(`${f.label} harus angka nol atau lebih.`);if(f.type==='ref'&&v&&!db.some(x=>x.id===v&&x.kind===f.kind))errors.push(`${f.label} tidak ditemukan.`)}
for(const [start,end] of [['start','end'],['failure','completed'],['date','returnDate']])if(r[start]&&r[end]&&r[end]<r[start])errors.push('Tanggal akhir tidak boleh mendahului awal.');
if(r.kind==='contract'&&r.group!=='Disewakan'&&!r.vendor)errors.push('Supplier wajib dipilih.');if(r.kind==='contract'&&r.group==='Disewakan'&&!r.counterparty)errors.push('Nama penyewa wajib diisi.');
if(r.kind==='asset'&&r.progress>100)errors.push('Progres maksimal 100%.');
if(r.kind==='repair'&&r.status==='Selesai'&&(!r.completed||!r.result))errors.push('Perbaikan selesai membutuhkan tanggal selesai dan hasil pekerjaan.');
if(r.kind==='reading'&&Number(r.current)<Number(r.previous))errors.push('Meter akhir lebih kecil dari awal. Reset/pergantian meter perlu penanganan terpisah.');
if(r.kind==='reading'&&db.some(x=>x.id!==r.id&&x.kind==='reading'&&x.contract===r.contract&&x.start===r.start&&x.end===r.end))errors.push('Pembacaan meter untuk sambungan dan periode ini sudah ada.');
if(r.kind==='document'&&r.contract&&r.end)errors.push('Kosongkan tanggal akhir dokumen; masa berlaku dibaca dari kontrak terkait.');
if(r.kind==='supply'&&(!(r.quantity>0)||r.fulfilled>r.quantity))errors.push('Jumlah diminta harus positif dan pemenuhan tidak boleh melebihinya.');
if(r.kind==='cleaning'&&r.done>r.planned)errors.push('Tugas selesai tidak boleh melebihi rencana.');
if(r.kind==='trip'&&r.endKm!==''&&r.endKm!==undefined&&Number(r.endKm)<Number(r.startKm))errors.push('Odometer akhir tidak boleh lebih kecil dari awal.');
if(r.kind==='booking'){if(r.endTime<=r.startTime)errors.push('Jam selesai harus setelah mulai.');if(r.status!=='Batal'&&db.some(x=>x.kind==='booking'&&x.id!==r.id&&x.status!=='Batal'&&x.site===r.site&&x.room.toLowerCase()===r.room.toLowerCase()&&x.date===r.date&&x.startTime<r.endTime&&x.endTime>r.startTime))errors.push('Ruang sudah dipesan pada waktu yang bertabrakan.')}
if(r.kind==='template'){if(!Number.isInteger(r.day)||r.day<1||r.day>31)errors.push('Hari invoice harus 1–31.');if(!r.next?.endsWith('-01'))errors.push('Awal periode recurring harus tanggal 1.');if(!(r.expected>0))errors.push('Perkiraan nominal harus positif.');if(r.end&&r.next>r.end)errors.push('Periode berikutnya melewati akhir penjadwalan.');const c=this.byId(db,r.contract);if(c&&c.vendor!==r.vendor)errors.push('Supplier template harus sama dengan kontrak.');if(c?.group==='Disewakan')errors.push('Disewakan memakai AR, bukan supplier bill template.');}
if(r.kind==='bill'){
if(r.invoiceNumber&&db.some(x=>x.kind==='bill'&&x.id!==r.id&&x.status!=='CANCELLED'&&x.vendor===r.vendor&&x.invoiceNumber?.trim().toLowerCase()===r.invoiceNumber.trim().toLowerCase()))errors.push('Nomor invoice supplier sudah dipakai oleh bill lain.');
if(!r.lines?.length)errors.push('Tambahkan minimal satu baris invoice.');
for(const l of r.lines||[]){if(l.amount!==''&&(!Number.isFinite(Number(l.amount))||Number(l.amount)<0))errors.push('Nominal baris harus nol atau lebih.');const ref=this.byId(db,l.ref);if(l.ref&&!ref)errors.push('Referensi baris tidak ditemukan.');if(ref?.kind==='contract'&&ref.group==='Disewakan')errors.push('Disewakan harus menggunakan invoice pelanggan / AR.');if(ref?.vendor&&ref.vendor!==r.vendor)errors.push('Supplier bill tidak cocok dengan referensi baris.');if(!l.site)errors.push('Lokasi biaya setiap baris wajib dipilih.');if(stage==='post'&&!l.account?.trim())errors.push('Finance harus mengisi akun setiap baris.');if(l.prepaid&&(!r.start||!r.end))errors.push('Prepaid memerlukan periode layanan pada bill.');}
if(this.gross(r)<0||this.net(r)<0)errors.push('Diskon/potongan melebihi nilai invoice.');
if(stage!=='save'){if(!r.invoiceNumber||!r.invoiceDate||!r.due)errors.push('Nomor invoice, tanggal invoice, dan jatuh tempo wajib diisi sebelum diajukan.');if(!r.files?.length)errors.push('Lampirkan invoice sebelum diajukan.');if(r.lines.some(l=>!(Number(l.amount)>0)))errors.push('Isi nominal aktual positif pada setiap baris.');}
if(stage==='post'&&r.review!=='Sesuai')errors.push('Finance perlu menyatakan hasil pemeriksaan Sesuai.');
if(stage==='post'&&r.expected){let delta=Math.abs(this.subtotal(r)-r.expected)/r.expected*100;if(delta>Number(r.tolerance||0)&&!r.reviewNote?.trim())errors.push('Nominal melewati ambang perkiraan; jelaskan hasil review selisih.');}
}
return [...new Set(errors)];
},
audit(r,actor,action,changes=''){(r.history??=[]).push({at:new Date().toISOString(),actor,action,changes})},
generate(db,t){if(t.status!=='Aktif')throw Error('Template sedang dijeda/dihentikan.');const c=this.byId(db,t.contract);if(!c||['Batal','Habis'].includes(c.status))throw Error('Kontrak tidak aktif untuk penagihan.');const p=this.period(t.next,t.frequency);if(c.start&&p.start<c.start)throw Error('Periode mendahului kontrak.');if((t.end&&p.end>t.end)||(c.end&&p.end>c.end))throw Error('Periode melewati akhir kontrak/template. Periode parsial harus dibuat manual.');const existing=db.find(r=>r.kind==='bill'&&r.template===t.id&&r.start===p.start);if(existing)return existing;
const r=seedRecord('bill',this.nextId(db,'bill'),`${t.name} · ${p.start.slice(0,7)}`,{vendor:t.vendor,site:t.site,template:t.id,expected:t.expected,tolerance:t.tolerance,start:p.start,end:p.end,expectedArrival:this.arrival(p.start,t.day),status:'WAITING_INVOICE',currency:'IDR',source:'Recurring Finance',review:'Belum diperiksa',tax:0,discount:0,withholding:0,lines:[{description:t.name,amount:t.mode==='Variabel'?'':t.expected,site:t.site,ref:t.contract,account:t.account||'',prepaid:t.prepaid==='Prepaid'}]});this.audit(r,'Finance','Draft recurring dibuat','Menunggu invoice aktual; tidak membuat AP atau pembayaran.');db.push(r);return r},
transition(db,r,action,role){if(r.kind!=='bill')throw Error('Aksi ini hanya untuk bill.');let stage=action==='post'?'post':'submit';if(action==='submit'){if(!['DRAFT','RETURNED','WAITING_INVOICE'].includes(r.status))throw Error('Status bill tidak bisa diajukan.')}else{if(role!=='Finance')throw Error('Aksi ini milik Finance.');if(action==='post'&&r.status!=='SUBMITTED')throw Error('Ajukan bill sebelum posting.');if(['return','hold'].includes(action)&&r.status!=='SUBMITTED')throw Error('Hanya bill masuk yang bisa dikembalikan atau ditahan.');if(action==='release'&&r.status!=='HOLD')throw Error('Bill tidak sedang ditahan.');}
if(['submit','post'].includes(action)){const errors=this.validate(db,r,stage);if(errors.length)throw Error(errors.join(' '));}if(['return','hold'].includes(action)&&!r.reviewNote?.trim())throw Error('Isi alasan pada catatan review.');if(action==='submit')r.review='Belum diperiksa';r.status=({submit:'SUBMITTED',post:'POSTED',return:'RETURNED',hold:'HOLD',release:'SUBMITTED'})[action];this.audit(r,role,`Status → ${r.status}`);return r},
pay(db,r,amount,date,bank,role){if(role!=='Finance'||r.status!=='POSTED')throw Error('Pembayaran simulasi hanya untuk bill POSTED oleh Finance.');if(this.byId(db,r.vendor)?.bankStatus!=='VERIFIED')throw Error('Rekening supplier belum diverifikasi Finance.');if(!Number.isFinite(amount)||amount<=0||amount>this.net(r)-this.paid(r))throw Error('Jumlah pembayaran harus positif dan tidak melebihi sisa.');if(!date||!bank?.trim())throw Error('Tanggal dan rekening sumber wajib diisi.');(r.payments??=[]).push({amount,date,bank,actor:role});this.audit(r,role,'Pembayaran simulasi dicatat',`${amount} IDR · ${date} · ${bank}`)}
};
